import { test, expect } from '@playwright/test';

test.describe('PDF Inline Viewer', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display uploaded PDF in inline viewer', async ({ page }) => {
    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload PDF');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Verify file name appears
    const fileNameDisplay = page.getByText('sample.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for file to process
    await page.waitForResponse(response => 
      response.url().includes('/api/files/upload') && response.status() === 200
    );

    // Verify inline viewer appears
    const viewerContainer = page.getByRole('region', { name: 'PDF Viewer' });
    await expect(viewerContainer).toBeVisible();

    // Verify PDF content is displayed
    const pdfContent = page.getByText('This is a sample PDF document');
    await expect(pdfContent).toBeVisible();

    // Verify document title is displayed
    const docTitle = page.getByText('Sample Document');
    await expect(docTitle).toBeVisible();
  });

  test('should handle invalid file types and display error message', async ({ page }) => {
    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload PDF');
    await fileInput.setInputFiles('playwright/fixtures/sample.jpg');

    // Verify error message appears for invalid file type
    const errorMessage = page.getByText('Invalid file type. Only PDF is allowed.');
    await expect(errorMessage).toBeVisible();

    // Verify inline viewer does not appear
    const viewerContainer = page.getByRole('region', { name: 'PDF Viewer' });
    await expect(viewerContainer).not.toBeVisible();

    // Verify upload button is disabled
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await expect(uploadButton).toBeDisabled();

    // Verify file name does not appear
    const fileNameDisplay = page.getByText('sample.jpg');
    await expect(fileNameDisplay).not.toBeVisible();

    // Verify error message disappears when file is removed
    await fileInput.clear();
    await expect(errorMessage).not.toBeVisible();
  });
});
